/**
 * Builds lib/geo/central-ohio.ts: SVG paths for the seven Columbus metro
 * counties, projected at a fixed viewBox, plus points for Columbus and a few
 * nearby communities.
 *
 * Runs at build time only (npm run build:map). The generated file is
 * committed, so the site never ships us-atlas, topojson-client or d3-geo.
 */
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { geoPath, geoTransverseMercator } from "d3-geo";
import { feature } from "topojson-client";

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outFile = path.join(root, "lib/geo/central-ohio.ts");

/** Ohio is state FIPS 39. County FIPS codes from the US Census. */
const COUNTIES = [
  { fips: "39049", name: "Franklin" },
  { fips: "39041", name: "Delaware" },
  { fips: "39089", name: "Licking" },
  { fips: "39045", name: "Fairfield" },
  { fips: "39159", name: "Union" },
  { fips: "39097", name: "Madison" },
  { fips: "39129", name: "Pickaway" },
];

/** Downtown Columbus, [longitude, latitude]. */
const COLUMBUS = [-82.9988, 39.9612];

/** Radius ring around Columbus, in miles. */
const RADIUS_MILES = 15;

/**
 * Approximate centers of a few communities inside the ring. The map draws
 * these as "ZIP code" dots, in the order they light up.
 */
const PLACES = [
  { name: "Worthington", lonLat: [-83.018, 40.0931] },
  { name: "Westerville", lonLat: [-82.9291, 40.1262] },
  { name: "New Albany", lonLat: [-82.8088, 40.0812] },
  { name: "Gahanna", lonLat: [-82.8793, 40.0192] },
  { name: "Reynoldsburg", lonLat: [-82.8121, 39.9548] },
  { name: "Canal Winchester", lonLat: [-82.8046, 39.8428] },
  { name: "Grove City", lonLat: [-83.093, 39.8815] },
  { name: "Hilliard", lonLat: [-83.1588, 40.0334] },
  { name: "Dublin", lonLat: [-83.1141, 40.0992] },
  { name: "Upper Arlington", lonLat: [-83.0624, 40.027] },
];

const WIDTH = 400;
const PADDING = 8;

const round = (n) => Math.round(n * 10) / 10;

const topology = JSON.parse(await readFile(require.resolve("us-atlas/counties-10m.json"), "utf8"));
const allCounties = feature(topology, topology.objects.counties).features;
const ohio = allCounties.filter((f) => String(f.id).startsWith("39"));

const features = COUNTIES.map(({ fips, name }) => {
  const f = ohio.find((c) => String(c.id) === fips);
  if (!f) throw new Error(`County ${name} (${fips}) not found in us-atlas`);
  return { ...f, properties: { ...f.properties, name } };
});

const collection = { type: "FeatureCollection", features };

// Transverse Mercator centered on Columbus keeps shapes and the radius ring
// true at this scale. Fit to a fixed width, then derive the height.
const projection = geoTransverseMercator()
  .rotate([-COLUMBUS[0], -COLUMBUS[1]])
  .fitWidth(WIDTH - PADDING * 2, collection);

const [[x0, y0], [, y1]] = geoPath(projection).bounds(collection);
projection.translate([
  projection.translate()[0] - x0 + PADDING,
  projection.translate()[1] - y0 + PADDING,
]);
const HEIGHT = Math.ceil(y1 - y0 + PADDING * 2);

const pathGen = geoPath(projection).digits(1);
const project = (lonLat) => projection(lonLat).map(round);

const counties = features.map((f) => ({
  name: f.properties.name,
  fips: String(f.id),
  path: pathGen(f),
  centroid: pathGen.centroid(f).map(round),
}));

const [cx, cy] = project(COLUMBUS);
// Distance from Columbus to a point RADIUS_MILES due north, in map units.
const milesPerDegreeLat = 69.05;
const [, ny] = project([COLUMBUS[0], COLUMBUS[1] + RADIUS_MILES / milesPerDegreeLat]);
const radius = round(Math.abs(cy - ny));

const places = PLACES.map((p) => {
  const [x, y] = project(p.lonLat);
  const inside = Math.hypot(x - cx, y - cy) < radius;
  if (!inside) throw new Error(`${p.name} falls outside the ${RADIUS_MILES} mile ring`);
  return { name: p.name, x, y };
});

const source = `/**
 * GENERATED by scripts/build-ohio-map.mjs. Do not edit by hand.
 * Run \`npm run build:map\` to regenerate.
 *
 * Source: us-atlas counties-10m (US Census cartographic boundaries),
 * projected with a transverse Mercator centered on Columbus.
 */

export type CountyShape = {
  name: string;
  fips: string;
  /** SVG path data in viewBox units. */
  path: string;
  /** Visual center of the county, for labels. */
  centroid: [number, number];
};

export type MapPoint = { name: string; x: number; y: number };

export const CENTRAL_OHIO_VIEWBOX = { width: ${WIDTH}, height: ${HEIGHT} } as const;

export const CENTRAL_OHIO_COUNTIES: CountyShape[] = ${JSON.stringify(counties, null, 2)};

export const COLUMBUS_POINT: MapPoint = ${JSON.stringify({ name: "Columbus", x: cx, y: cy })};

/** A ${RADIUS_MILES} mile radius around Columbus, in viewBox units. */
export const COLUMBUS_RADIUS = { miles: ${RADIUS_MILES}, r: ${radius} } as const;

/** Communities inside the radius, in the order they light up. */
export const RADIUS_PLACES: MapPoint[] = ${JSON.stringify(places, null, 2)};
`;

await mkdir(path.dirname(outFile), { recursive: true });
await writeFile(outFile, source);
console.log(
  `Wrote ${path.relative(root, outFile)}: ${counties.length} counties, viewBox ${WIDTH}x${HEIGHT}, ` +
    `radius ${radius}, ${(source.length / 1024).toFixed(1)} KB`,
);
